function solve(history, queries) {
  const groups = new Map();
  for (let h = 0; h < history.length; h++) {
    const entry = history[h];
    if (!Array.isArray(entry) || entry.length < 3) continue;
    const index = entry[1];
    if (!groups.has(index)) groups.set(index, []);
    groups.get(index).push({ snap: entry[0], seq: h, value: entry[2] });
  }
  for (const group of groups.values()) {
    group.sort((a, b) => (a.snap - b.snap) || (a.seq - b.seq));
  }
  const answers = [];
  for (let q = 0; q < queries.length; q++) {
    const query = queries[q];
    if (!Array.isArray(query) || query.length < 2) {
      answers.push(0);
      continue;
    }
    const target = query[0];
    const index = query[1];
    const group = groups.get(index);
    if (group === undefined) {
      answers.push(0);
      continue;
    }
    let lo = 0;
    let hi = group.length - 1;
    let found = -1;
    while (lo <= hi) {
      const mid = lo + Math.floor((hi - lo) / 2);
      if (group[mid].snap <= target) {
        found = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    answers.push(found === -1 ? 0 : group[found].value);
  }
  return answers;
}
